P30-counting-bits:
def count_bits(n):
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = dp[i >> 1] + (i & 1)   # i = (i // 2) with one more low bit
    return dp

P30-counting-bits#each:
def count_bits(n):
    def popcount(x):
        c = 0
        while x:
            x &= x - 1                 # clear the lowest set bit
            c += 1
        return c

    return [popcount(i) for i in range(n + 1)]

P30-number-of-1-bits:
def hamming_weight(n):
    count = 0
    while n:
        n &= n - 1                     # clears the lowest set bit
        count += 1
    return count

P30-number-of-1-bits#shift:
def hamming_weight(n):
    count = 0
    for i in range(32):
        count += (n >> i) & 1          # test every position
    return count

P30-reverse-bits:
def reverse_bits(n):
    res = 0
    for _ in range(32):
        res = (res << 1) | (n & 1)     # push n's lowest bit onto res
        n >>= 1
    return res

P30-single-number:
def single_number(nums):
    acc = 0
    for x in nums:
        acc ^= x                       # pairs cancel: a ^ a = 0
    return acc

P30-single-number-ii:
def single_number(nums):
    ones = twos = 0                    # per-bit count mod 3
    for x in nums:
        ones = (ones ^ x) & ~twos
        twos = (twos ^ x) & ~ones
    return ones

P30-sum-of-two-integers:
def get_sum(a, b):
    MASK = 0xFFFFFFFF                  # Python ints are unbounded: emulate 32 bits
    a, b = a & MASK, b & MASK
    while b:
        a, b = (a ^ b) & MASK, ((a & b) << 1) & MASK   # sum without carry, carry
    return a if a <= 0x7FFFFFFF else ~(a ^ MASK)       # back to a signed int
